#include <iostream>
#include <windows.h>
#include <sql.h>
#include <sqlext.h>

int main() {
    SQLHENV env;
    SQLHDBC dbc;
    SQLRETURN ret;

    // Allocate environment handle
    SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &env);
    SQLSetEnvAttr(env, SQL_ATTR_ODBC_VERSION, (void*)SQL_OV_ODBC3, 0);

    // Allocate connection handle
    SQLAllocHandle(SQL_HANDLE_DBC, env, &dbc);

    // Connect to the database
    ret = SQLConnect(dbc, (SQLCHAR*)"myServerName", SQL_NTS, 
                     (SQLCHAR*)"myUsername", SQL_NTS, 
                     (SQLCHAR*)"myPassword", SQL_NTS);

    if (ret != SQL_SUCCESS && ret != SQL_SUCCESS_WITH_INFO) {
        // Error handling...
        return -1;
    }

    // Do something with the connected database...

    // Disconnect from the database and free handles
    SQLDisconnect(dbc);
    SQLFreeHandle(SQL_HANDLE_DBC, dbc);
    SQLFreeHandle(SQL_HANDLE_ENV, env);

    return 0;
}
```

In this example, `SQLAllocHandle` is used to allocate an environment handle and a connection handle. `SQLSetEnvAttr` is used to set the ODBC version to 3.0. `SQLConnect` is used to connect to the database, providing the server name, username, and password. Once the connection is established, you can run SQL queries or access the database as needed. Finally, `SQLDisconnect` is used to disconnect from the database and `SQLFreeHandle` is used to free the allocated handles.
